#!/usr/bin/env python3
from pwn import *
import json
import gmpy2
from collections import namedtuple
import time
import re

# Set up connection
HOST = 'crypto.chal.csaw.io'
PORT = 5000

Point = namedtuple("Point", "x y")
O = 'Origin'

# P-256 curve parameters
curve_p256 = {
    "p": gmpy2.mpz(2**256 - 2**224 + 2**192 + 2**96 - 1),
    "a": gmpy2.mpz(-0x3),
    "b": gmpy2.mpz(0x5ac635d8aa3a93e7b3ebbd55769886bc651d06b0cc53b0f63bce3c3e27d2604b),
    "n": gmpy2.mpz(0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551)
}

def receive_until_prompt(r):
    """Receive data until we get a '>' or timeout"""
    data = b""
    try:
        data = r.recvuntil(b">", timeout=2)
    except EOFError:
        pass
    return data.decode().strip()

def send_json_and_receive(r, data):
    """Send JSON data to server and receive response"""
    json_data = json.dumps(data)
    log.info(f"Sending: {json_data}")
    r.sendline(json_data.encode())
    time.sleep(0.5)

    response = receive_until_prompt(r)
    log.info(f"Received: {response}")
    return response

def parse_point(point_str):
    """Parse a point from the challenge response"""
    try:
        # Extract x and y coordinates using regex
        coords = re.findall(r'Point\(x=(\d+), y=(\d+)\)', point_str)
        if coords:
            x, y = map(int, coords[0])
            return Point(x, y)
    except Exception as e:
        log.error(f"Error parsing point: {str(e)}")
    return None

def check_point(P, curve):
    """Check if a point is on the curve"""
    if P == O:
        return True
    p, a, b = curve["p"], curve["a"], curve["b"]
    return (P.y**2 - (P.x**3 + a*P.x + b)) % p == 0 and 0 <= P.x < p and 0 <= P.y < p

def point_addition(P, Q, curve):
    """Add two points on the curve"""
    p, a, b = curve["p"], curve["a"], curve["b"]
    if P == O:
        return Q
    elif Q == O:
        return P
    elif Q == Point(P.x, (-P.y) % p):
        return O
    else:
        if P == Q:
            lam = (3*P.x**2 + a) * pow(2*P.y, -1, p)
            lam %= p
        else:
            lam = (Q.y - P.y) * pow((Q.x - P.x), -1, p)
            lam %= p
    Rx = (lam**2 - P.x - Q.x) % p
    Ry = (lam*(P.x - Rx) - P.y) % p
    return Point(Rx, Ry)

def double_and_add(P, n, curve):
    """Scalar multiplication on the curve"""
    Q = P
    R = O
    while n > 0:
        if n % 2 == 1:
            if R == O:
                R = Q
            else:
                R = point_addition(R, Q, curve)
        Q = point_addition(Q, Q, curve)
        n = n // 2
    return R

def main():
    # Create connection
    context.log_level = 'debug'

    try:
        r = remote(HOST, PORT)

        # Wait for initial prompt
        initial_response = receive_until_prompt(r)
        log.info(f"Initial response: {initial_response}")

        # Step 1: Select P-256 curve
        log.info("Selecting P-256 curve...")
        curve_data = {"curve": "curve_p256"}
        response = send_json_and_receive(r, curve_data)

        # Step 2: Send generator point
        log.info("Sending generator point...")
        G = Point(
            0x6b17d1f2e12c4247f8bce6e563a440f277037d812deb33a0f4a13945d898c296,
            0x4fe342e2fe1a7f9b8ee7eb4a7c0f9e162bce33576b315ececbb6406837bf51f5
        )
        generator_data = {
            "Gx": hex(G.x),
            "Gy": hex(G.y)
        }
        response = send_json_and_receive(r, generator_data)

        # Step 3: Parse challenge point and try to solve DLP
        challenge_point = None
        for line in response.split('\n'):
            if "Challenge:" in line:
                point_str = line.split("Challenge:")[1].strip()
                challenge_point = parse_point(point_str)
                log.info(f"Parsed challenge point: {challenge_point}")

        if challenge_point and check_point(challenge_point, curve_p256):
            # Try some small values first
            for d in range(1, 1000):
                if double_and_add(G, d, curve_p256) == challenge_point:
                    log.success(f"Found d = {d}")
                    response = send_json_and_receive(r, {"d": hex(d)})
                    if "flag{" in response:
                        log.success(f"Flag found: {response}")
                    break

    except Exception as e:
        log.error(f"Error occurred: {str(e)}")
    finally:
        r.close()

if __name__ == "__main__":
    main()

